// Build a clean text blob for Gemini: subject + from + date + plain body.
// We strip HTML and collapse whitespace so the LLM gets a tidy input.
const item = $input.first().json;

const subject = item.subject || item.headers?.subject || '';
const from    = item.from    || item.headers?.from    || '';
const date    = item.date    || item.headers?.date    || '';

// Gmail "simplify" puts the body in item.text or item.textPlain or item.body
let body = item.text || item.textPlain || item.body || item.snippet || '';

// If we still got HTML, strip tags crudely
if (/<[a-z][\s\S]*>/i.test(body)) {
  body = body
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<\/?[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"');
}

body = body.replace(/\s+/g, ' ').trim().slice(0, 8000); // cap length

return [{
  json: {
    messageId: item.id,
    threadId:  item.threadId,
    subject,
    from,
    date,
    body
  }
}];

