// Parse Gemini's response and normalize it. Falls back to a safe default if parsing fails.
const out = $input.first().json;
const prepared = $('Prepare Email Text').first().json;

let parsed = null;
try {
  // Gemini returns { candidates: [ { content: { parts: [ { text: "..." } ] } } ] }
  const text = out?.candidates?.[0]?.content?.parts?.[0]?.text;
  if (text) parsed = JSON.parse(text);
} catch (e) {
  parsed = null;
}

const safe = parsed || {
  summary: (prepared.body || '').slice(0, 200) || '(no summary available)',
  priority: 'Low',
  action_items: [],
  deadline: null
};

return [{
  json: {
    messageId: prepared.messageId,
    subject:   prepared.subject,
    from:      prepared.from,
    date:      prepared.date,
    summary:   String(safe.summary || '').slice(0, 1000),
    priority:  ['Low', 'Medium', 'High'].includes(safe.priority) ? safe.priority : 'Low',
    action_items: Array.isArray(safe.action_items) ? safe.action_items.slice(0, 10).map(String) : [],
    deadline: safe.deadline ? String(safe.deadline).slice(0, 200) : null
  }
}];

// Build a Slack Block Kit message.
// Header (subject), context (from + date + priority), summary, action items, deadline, footer with messageId.

const d = $input.first().json;

const priorityEmoji = d.priority === 'High' ? '🔴'
                    : d.priority === 'Medium' ? '🟡'
                    : '🟢';

const priorityColor = d.priority === 'High' ? '#e01e5a'
                     : d.priority === 'Medium' ? '#ecb22e'
                     : '#2eb67d';

const blocks = [
  {
    type: 'header',
    text: { type: 'plain_text', text: (d.subject || '(no subject)').slice(0, 150), emoji: false }
  },
  {
    type: 'context',
    elements: [
      { type: 'mrkdwn', text: `*From:* ${d.from || 'unknown'}` },
      { type: 'mrkdwn', text: `*Date:* ${d.date || 'unknown'}` },
      { type: 'mrkdwn', text: `*Priority:* ${priorityEmoji} ${d.priority}` }
    ]
  },
  { type: 'divider' },
  {
    type: 'section',
    text: { type: 'mrkdwn', text: `*Summary*\n${d.summary || '_no summary_'}` }
  }
];

if (Array.isArray(d.action_items) && d.action_items.length) {
  blocks.push({
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: '*Action items*\n' + d.action_items.map(a => `• ${a}`).join('\n')
    }
  });
}

if (d.deadline) {
  blocks.push({
    type: 'section',
    text: { type: 'mrkdwn', text: `*Deadline:* ⏰ ${d.deadline}` }
  });
}

blocks.push({ type: 'divider' });
blocks.push({
  type: 'context',
  elements: [
    { type: 'mrkdwn', text: `messageId: \`${d.messageId}\`` }
  ]
});

return [{
  json: {
    channel: 'REPLACE_WITH_SLACK_CHANNEL_ID',
    text: `📧 ${d.subject || 'New email'} — ${priorityEmoji} ${d.priority}`,
    blocks: JSON.stringify(blocks),
    attachments: JSON.stringify([{ color: priorityColor }]),
    messageId: d.messageId,
    subject:   d.subject,
    from:      d.from,
    priority:  d.priority
  }
}];
